import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { getIdea, refineIdea } from "@/api/ideas";
import { ScoreBadge } from "@/components/ideas/score-badge";
import { ExportButton } from "@/components/ideas/export-button";
import { FeedbackForm } from "@/components/ideas/feedback-form";
import { NoveltyReportView } from "@/components/ideas/novelty-report-view";
import { FeasibilityReportView } from "@/components/ideas/feasibility-report-view";
import { MarkdownRenderer } from "@/components/markdown/markdown-renderer";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { useParams, useNavigate } from "react-router-dom";
import { ArrowLeft, RefreshCw, Loader2, GitBranch } from "lucide-react";
import { toast } from "sonner";

export default function IdeaDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const ideaId = Number(id);

  const { data, isLoading } = useQuery({
    queryKey: ["idea", ideaId],
    queryFn: () => getIdea(ideaId),
    enabled: !isNaN(ideaId),
  });

  const refineMutation = useMutation({
    mutationFn: () => refineIdea(ideaId),
    onSuccess: () => {
      toast.success("Idea refined — scores updated");
      queryClient.invalidateQueries({ queryKey: ["idea", ideaId] });
    },
    onError: (err) => {
      toast.error(err.message || "Refinement failed");
    },
  });

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-8 w-32" />
        <Skeleton className="h-10 w-3/4" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (!data?.idea) {
    return (
      <div className="text-center py-12 text-muted-foreground">
        <p>Idea not found.</p>
      </div>
    );
  }

  const idea = data.idea;

  return (
    <div className="space-y-6">
      <div>
        <Button variant="ghost" size="sm" onClick={() => navigate("/ideas")}>
          <ArrowLeft className="mr-2 h-4 w-4" />
          Back to Ideas
        </Button>
      </div>

      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">{idea.title}</h1>
          <p className="text-muted-foreground mt-1">{idea.domain}</p>
          <div className="flex flex-wrap gap-2 mt-3">
            {idea.novelty_score != null && (
              <ScoreBadge score={idea.novelty_score} scale="novelty" />
            )}
            {idea.feasibility_score != null && (
              <ScoreBadge score={idea.feasibility_score} scale="feasibility" />
            )}
            {idea.overall_score != null && (
              <span className="inline-flex items-center rounded-full bg-primary/10 px-2 py-0.5 text-xs font-semibold text-primary">
                Overall: {idea.overall_score.toFixed(2)}
              </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <ExportButton
            proposalMd={idea.proposal_md}
            proposalLatex={idea.proposal_latex}
            title={idea.title}
          />
          <Button
            variant="outline"
            size="sm"
            onClick={() => refineMutation.mutate()}
            disabled={refineMutation.isPending}
          >
            {refineMutation.isPending ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <RefreshCw className="mr-2 h-4 w-4" />
            )}
            Refine
          </Button>
        </div>
      </div>

      <Separator />

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Problem Statement</CardTitle>
        </CardHeader>
        <CardContent>
          <MarkdownRenderer content={idea.problem_statement} />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Proposed Method</CardTitle>
        </CardHeader>
        <CardContent>
          <MarkdownRenderer content={idea.proposed_method} />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Expected Contributions</CardTitle>
        </CardHeader>
        <CardContent>
          <MarkdownRenderer content={idea.expected_contributions} />
        </CardContent>
      </Card>

      {idea.source_gap_ids && idea.source_gap_ids.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <GitBranch className="h-4 w-4" />
              Source Research Gaps
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ul className="space-y-2">
              {idea.source_gap_ids.map((gapId, idx) => (
                <li key={idx} className="flex items-center gap-2 text-sm">
                  <span className="inline-block h-2 w-2 rounded-full bg-amber-500 flex-shrink-0" />
                  {gapId}
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>
      )}

      {(idea.proposal_md || idea.novelty_report || idea.feasibility_report) && (
        <Tabs defaultValue={idea.proposal_md ? "proposal" : idea.novelty_report ? "novelty" : "feasibility"}>
          <TabsList>
            {idea.proposal_md && <TabsTrigger value="proposal">Proposal</TabsTrigger>}
            {idea.novelty_report && <TabsTrigger value="novelty">Novelty Report</TabsTrigger>}
            {idea.feasibility_report && <TabsTrigger value="feasibility">Feasibility Report</TabsTrigger>}
          </TabsList>
          {idea.proposal_md && (
            <TabsContent value="proposal">
              <Card>
                <CardContent className="pt-6">
                  <MarkdownRenderer content={idea.proposal_md} />
                </CardContent>
              </Card>
            </TabsContent>
          )}
          {idea.novelty_report && (
            <TabsContent value="novelty">
              <Card>
                <CardContent className="pt-6">
                  <NoveltyReportView report={idea.novelty_report} />
                </CardContent>
              </Card>
            </TabsContent>
          )}
          {idea.feasibility_report && (
            <TabsContent value="feasibility">
              <Card>
                <CardContent className="pt-6">
                  <FeasibilityReportView report={idea.feasibility_report} />
                </CardContent>
              </Card>
            </TabsContent>
          )}
        </Tabs>
      )}

      <FeedbackForm ideaId={ideaId} />
    </div>
  );
}

import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { listIdeas } from "@/api/ideas";
import { IdeaCard } from "@/components/ideas/idea-card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { useNavigate } from "react-router-dom";
import { Search, ChevronLeft, ChevronRight } from "lucide-react";

const SORT_OPTIONS = [
  { value: "date", label: "Newest First" },
  { value: "score", label: "Overall Score" },
  { value: "novelty", label: "Novelty Score" },
  { value: "feasibility", label: "Feasibility Score" },
] as const;

export default function IdeasBrowser() {
  const navigate = useNavigate();
  const [searchText, setSearchText] = useState("");
  const [domainFilter, setDomainFilter] = useState("");
  const [sortBy, setSortBy] = useState("date");
  const [minScore, setMinScore] = useState(0);
  const [page, setPage] = useState(0);
  const limit = 20;

  const queryParams = useMemo(
    () => ({
      domain: domainFilter || undefined,
      search: searchText || undefined,
      sort_by: sortBy !== "date" ? sortBy : undefined,
      min_score: minScore > 0 ? minScore : undefined,
      limit,
      offset: page * limit,
    }),
    [domainFilter, searchText, sortBy, minScore, page, limit],
  );

  const { data, isLoading } = useQuery({
    queryKey: ["ideas", queryParams],
    queryFn: () => listIdeas(queryParams),
  });

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Research Ideas</h1>
        <p className="text-muted-foreground">
          Browse generated ideas with novelty and feasibility scores.
        </p>
      </div>

      {/* Search, Sort, and Filter Controls */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Search ideas by title..."
            value={searchText}
            onChange={(e) => {
              setSearchText(e.target.value);
              setPage(0);
            }}
            className="pl-9"
            aria-label="Search ideas by title"
          />
        </div>

        <div className="flex items-end gap-4">
          <div className="w-[180px]">
            <label className="text-xs text-muted-foreground mb-1 block">Sort by</label>
            <Select
              value={sortBy}
              onValueChange={(v) => {
                setSortBy(v);
                setPage(0);
              }}
            >
              <SelectTrigger aria-label="Sort ideas by">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {SORT_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value}>
                    {opt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="w-[160px]">
            <label className="text-xs text-muted-foreground mb-1 block">
              Min Score: {minScore.toFixed(1)}
            </label>
            <Slider
              value={[minScore]}
              onValueChange={(v) => {
                setMinScore(v[0]);
                setPage(0);
              }}
              min={0}
              max={1}
              step={0.1}
              aria-label="Minimum overall score filter"
            />
          </div>

          <div className="w-[160px]">
            <Input
              placeholder="Filter by domain..."
              value={domainFilter}
              onChange={(e) => {
                setDomainFilter(e.target.value);
                setPage(0);
              }}
              aria-label="Filter by domain"
            />
          </div>
        </div>
      </div>

      {isLoading ? (
        <div className="grid gap-3 md:grid-cols-2">
          {Array.from({ length: 6 }).map((_, i) => (
            <Skeleton key={i} className="h-28 w-full" />
          ))}
        </div>
      ) : data?.ideas.length ? (
        <>
          <p className="text-sm text-muted-foreground">
            {data.total} idea{data.total !== 1 ? "s" : ""} found
          </p>
          <div className="grid gap-3 md:grid-cols-2">
            {data.ideas.map((idea) => (
              <IdeaCard
                key={idea.id}
                idea={idea}
                onClick={() => navigate(`/ideas/${idea.id}`)}
              />
            ))}
          </div>
          {data.total > limit && (
            <div className="flex items-center justify-between pt-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page === 0}
                onClick={() => setPage((p) => p - 1)}
              >
                <ChevronLeft className="mr-1 h-4 w-4" />
                Previous
              </Button>
              <span className="text-sm text-muted-foreground">
                Page {page + 1} of {Math.ceil(data.total / limit)}
              </span>
              <Button
                variant="outline"
                size="sm"
                disabled={(page + 1) * limit >= data.total}
                onClick={() => setPage((p) => p + 1)}
              >
                Next
                <ChevronRight className="ml-1 h-4 w-4" />
              </Button>
            </div>
          )}
        </>
      ) : (
        <div className="text-center py-12 text-muted-foreground">
          <p>No ideas found{searchText ? ` for "${searchText}"` : domainFilter ? ` for "${domainFilter}"` : ""}.</p>
        </div>
      )}
    </div>
  );
}

