import { Button } from "@/components/ui/button";
import { Download } from "lucide-react";

interface ExportButtonProps {
  proposalMd: string | null;
  proposalLatex: string | null;
  title: string;
}

function download(filename: string, content: string, mime: string) {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

export function ExportButton({ proposalMd, proposalLatex, title }: ExportButtonProps) {
  if (!proposalMd && !proposalLatex) return null;

  const safeName = title.replace(/[^a-zA-Z0-9]/g, "_").slice(0, 50);

  return (
    <div className="flex items-center gap-2">
      {proposalMd && (
        <Button
          variant="outline"
          size="sm"
          onClick={() => download(`${safeName}.md`, proposalMd, "text/markdown")}
        >
          <Download className="mr-2 h-4 w-4" />
          Markdown
        </Button>
      )}
      {proposalLatex && (
        <Button
          variant="outline"
          size="sm"
          onClick={() => download(`${safeName}.tex`, proposalLatex, "application/x-latex")}
        >
          <Download className="mr-2 h-4 w-4" />
          LaTeX
        </Button>
      )}
    </div>
  );
}

import { apiFetch } from "./client";
import type { IdeaListResponse, IdeaDetail, IdeaFeedbackRequest } from "./types";

export function listIdeas(params?: {
  domain?: string;
  min_score?: number;
  search?: string;
  sort_by?: string;
  sort_order?: string;
  limit?: number;
  offset?: number;
}): Promise<IdeaListResponse> {
  const search = new URLSearchParams();
  if (params?.domain) search.set("domain", params.domain);
  if (params?.min_score !== undefined) search.set("min_score", String(params.min_score));
  if (params?.search) search.set("search", params.search);
  if (params?.sort_by) search.set("sort_by", params.sort_by);
  if (params?.sort_order) search.set("sort_order", params.sort_order);
  if (params?.limit) search.set("limit", String(params.limit));
  if (params?.offset) search.set("offset", String(params.offset));
  const qs = search.toString();
  return apiFetch(`/ideas/${qs ? `?${qs}` : ""}`);
}

export function getIdea(id: number): Promise<{ idea: IdeaDetail }> {
  return apiFetch(`/ideas/${id}`);
}

export function submitFeedback(
  id: number,
  req: IdeaFeedbackRequest,
): Promise<{ id: number; user_rating: number; user_notes: string | null }> {
  return apiFetch(`/ideas/${id}/feedback`, {
    method: "POST",
    body: JSON.stringify(req),
  });
}

export function refineIdea(
  id: number,
): Promise<{ id: number; novelty_score: number; feasibility_score: number; proposal_title: string }> {
  return apiFetch(`/ideas/${id}/refine`, { method: "POST" });
}

import { API_PREFIX } from "@/lib/constants";

export class ApiError extends Error {
  constructor(
    public status: number,
    public detail: string,
  ) {
    super(detail);
    this.name = "ApiError";
  }
}

function getBaseUrl(): string {
  return localStorage.getItem("erock_api_url") || "";
}

function getApiKey(): string {
  return localStorage.getItem("erock_api_key") || "";
}

export async function apiFetch<T>(path: string, options?: RequestInit): Promise<T> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    ...(options?.headers as Record<string, string> | undefined),
  };
  const key = getApiKey();
  if (key) {
    headers["X-API-Key"] = key;
  }

  const res = await fetch(`${getBaseUrl()}${API_PREFIX}${path}`, {
    ...options,
    headers,
  });

  if (!res.ok) {
    const body = await res.json().catch(() => ({ detail: res.statusText }));
    throw new ApiError(res.status, body.detail || body.error || res.statusText);
  }

  if (res.status === 204) return undefined as T;
  return res.json();
}

/** Test backend connectivity via /health endpoint. */
export async function testConnection(baseUrl?: string): Promise<{ ok: true; version: string } | { ok: false; error: string }> {
  try {
    const base = baseUrl ?? getBaseUrl();
    const res = await fetch(`${base}/health`, {
      method: "GET",
      headers: { "Content-Type": "application/json" },
    });
    if (!res.ok) {
      return { ok: false, error: `HTTP ${res.status}` };
    }
    const data = await res.json();
    return { ok: true, version: data.version ?? "unknown" };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

/** Detailed status response from /api/v1/status/detailed. */
export interface DetailedStatus {
  version: string;
  provider: string;
  db_status: string;
}

/** Fetch detailed status from the backend. */
export async function getDetailedStatus(): Promise<DetailedStatus> {
  return apiFetch<DetailedStatus>("/status/detailed");
}

/** Fetch-based SSE connection with Authorization header (BATCH-31, HB-01).
 *  Replaces the legacy sseUrl() which put API keys in query params.
 */
export function sseFetch(
  path: string,
  callbacks: {
    onEvent: (data: string) => void;
    onOpen?: () => void;
    onError?: (error: Error) => void;
  },
): AbortController {
  const controller = new AbortController();
  const headers: Record<string, string> = {};
  const key = getApiKey();
  if (key) {
    headers["X-API-Key"] = key;
  }
  const base = getBaseUrl() || window.location.origin;
  const url = `${base}${API_PREFIX}${path}`;

  (async () => {
    try {
      const response = await fetch(url, { headers, signal: controller.signal });
      if (!response.ok) {
        throw new Error(`SSE connection failed: HTTP ${response.status}`);
      }
      callbacks.onOpen?.();
      const reader = response.body!.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        // SSE events are separated by blank lines (\n\n)
        const parts = buffer.split("\n\n");
        buffer = parts.pop() || "";
        for (const part of parts) {
          for (const line of part.split("\n")) {
            if (line.startsWith("data: ")) {
              callbacks.onEvent(line.slice(6));
            }
          }
        }
      }
    } catch (err) {
      if ((err as Error).name !== "AbortError" && callbacks.onError) {
        callbacks.onError(err instanceof Error ? err : new Error(String(err)));
      }
    }
  })();

  return controller;
}

// --- Pipeline ---

export interface PipelineRunRequest {
  domain?: string;
  max_gaps?: number;
  generation_rounds?: number | null;
  ideas_per_round?: number | null;
  search_queries?: string[] | null;
  run_novelty?: boolean;
  run_feasibility?: boolean;
  run_synthesis?: boolean;
  export_format?: string;
  session_id?: string | null;
}

export interface PipelineRunSummary {
  id: number;
  status: "pending" | "running" | "completed" | "failed";
  domain: string;
  current_stage: string | null;
  ideas_count: number;
  session_id: string | null;
  created_at: string;
  completed_at: string | null;
  error_message: string | null;
}

export interface PipelineRunDetail extends PipelineRunSummary {
  config: Record<string, unknown>;
  stages_completed: string[];
  ideas: IdeaSummary[];
}

export interface TriggerRunResponse {
