import { apiFetch } from "./client";

// --- Export ---

export interface ExportPdfRequest {
  idea_id: number;
}

export interface BulkExportRequest {
  idea_ids: number[];
  format?: "pdf" | "markdown";
}

export function exportPdf(req: ExportPdfRequest): Promise<Blob> {
  return apiFetch(`/export/pdf`, {
    method: "POST",
    body: JSON.stringify(req),
    headers: { Accept: "application/pdf" },
  }).then(() => {
    // apiFetch returns JSON, but we need a blob for file download
    // Use raw fetch for binary responses
    return rawExportFetch("/export/pdf", JSON.stringify(req));
  });
}

export function bulkExport(req: BulkExportRequest): Promise<Blob> {
  return rawExportFetch("/export/bulk", JSON.stringify(req));
}

async function rawExportFetch(path: string, body: string): Promise<Blob> {
  const { API_PREFIX } = await import("@/lib/constants");
  const baseUrl = localStorage.getItem("erock_api_url") || "";
  const key = localStorage.getItem("erock_api_key") || "";
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
  };
  if (key) headers["X-API-Key"] = key;

  const res = await fetch(`${baseUrl}${API_PREFIX}${path}`, {
    method: "POST",
    headers,
    body,
  });

  if (!res.ok) {
    const errBody = await res.json().catch(() => ({ detail: res.statusText }));
    throw new Error(errBody.detail || errBody.error || res.statusText);
  }

  return res.blob();
}

// --- Plugins ---

export interface Plugin {
  name: string;
  version: string;
  description: string;
  enabled: boolean;
  metadata: Record<string, unknown>;
}

export interface PluginListResponse {
  plugins: Plugin[];
  total: number;
}

export function listPlugins(): Promise<PluginListResponse> {
  return apiFetch("/plugins/");
}

export function installPlugin(req: {
  name: string;
  version?: string;
  description?: string;
}): Promise<Plugin> {
  return apiFetch("/plugins/install", {
    method: "POST",
    body: JSON.stringify(req),
  });
}

import { useState } from "react";
import { exportPdf, bulkExport } from "@/api/exports";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Download, Loader2 } from "lucide-react";
import { toast } from "sonner";

interface ExportDialogProps {
  /** Single idea export — pass idea_id */
  ideaId?: number;
  /** Bulk export — pass array of idea_ids */
  ideaIds?: number[];
  title?: string;
}

function downloadBlob(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

export function ExportDialog({ ideaId, ideaIds, title }: ExportDialogProps) {
  const [format, setFormat] = useState<"pdf" | "markdown">("pdf");
  const [loading, setLoading] = useState(false);
  const [open, setOpen] = useState(false);

  const isBulk = !!ideaIds && ideaIds.length > 0;

  async function handleExport() {
    setLoading(true);
    try {
      if (isBulk) {
        const blob = await bulkExport({ idea_ids: ideaIds!, format });
        const timestamp = new Date().toISOString().slice(0, 10);
        downloadBlob(blob, `ideas_export_${timestamp}.zip`);
        toast.success(`Exported ${ideaIds!.length} idea(s) as ${format.toUpperCase()}`);
      } else if (ideaId) {
        const blob = await exportPdf({ idea_id: ideaId });
        const safeTitle = (title || "idea").replace(/[^a-zA-Z0-9]/g, "_").slice(0, 50);
        downloadBlob(blob, `${safeTitle}.${format === "pdf" ? "pdf" : "html"}`);
        toast.success("PDF exported successfully");
      }
      setOpen(false);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Export failed");
    } finally {
      setLoading(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" data-testid="export-dialog-trigger">
          <Download className="mr-2 h-4 w-4" />
          {isBulk ? `Export ${ideaIds!.length} Ideas` : "Export"}
        </Button>
      </DialogTrigger>
      <DialogContent data-testid="export-dialog">
        <DialogHeader>
          <DialogTitle>
            {isBulk ? "Bulk Export Ideas" : "Export Idea"}
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div>
            <label className="text-sm font-medium mb-1 block">Format</label>
            <Select
              value={format}
              onValueChange={(v) => setFormat(v as "pdf" | "markdown")}
            >
              <SelectTrigger data-testid="export-format-select" aria-label="Export format">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="pdf">PDF</SelectItem>
                <SelectItem value="markdown">Markdown (ZIP)</SelectItem>
              </SelectContent>
            </Select>
          </div>
          {isBulk && (
            <p className="text-sm text-muted-foreground">
              {ideaIds!.length} idea(s) will be exported as a ZIP archive.
            </p>
          )}
          <Button
            onClick={handleExport}
            disabled={loading}
            data-testid="export-submit-btn"
            className="w-full"
          >
            {loading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Exporting...
              </>
            ) : (
              <>
                <Download className="mr-2 h-4 w-4" />
                Export {format === "pdf" ? "PDF" : "Markdown ZIP"}
              </>
            )}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { listPlugins, installPlugin, type Plugin } from "@/api/exports";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Puzzle, Plus, Loader2, Search } from "lucide-react";
import { toast } from "sonner";

export default function PluginsPage() {
  const queryClient = useQueryClient();
  const [searchText, setSearchText] = useState("");
  const [newPluginName, setNewPluginName] = useState("");
  const [newPluginDesc, setNewPluginDesc] = useState("");

  const { data, isLoading } = useQuery({
    queryKey: ["plugins"],
    queryFn: listPlugins,
  });

  const installMutation = useMutation({
    mutationFn: installPlugin,
    onSuccess: () => {
      toast.success("Plugin installed successfully");
      queryClient.invalidateQueries({ queryKey: ["plugins"] });
      setNewPluginName("");
      setNewPluginDesc("");
    },
    onError: (err) => {
      toast.error(err.message || "Installation failed");
    },
  });

  const plugins = data?.plugins ?? [];
  const filtered = plugins.filter(
    (p) =>
      p.name.toLowerCase().includes(searchText.toLowerCase()) ||
      p.description.toLowerCase().includes(searchText.toLowerCase()),
  );

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Plugins</h1>
        <p className="text-muted-foreground">
          Browse and manage platform plugins.
        </p>
      </div>

      {/* Search */}
      <div className="relative max-w-md">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input
          placeholder="Search plugins..."
          value={searchText}
          onChange={(e) => setSearchText(e.target.value)}
          className="pl-9"
          aria-label="Search plugins"
        />
      </div>

      {/* Install New Plugin */}
      <Card data-testid="plugin-install-card">
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Plus className="h-4 w-4" />
            Install Plugin
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-end gap-3">
            <div className="flex-1">
              <label className="text-xs text-muted-foreground mb-1 block">Plugin Name</label>
              <Input
                placeholder="my-plugin"
                value={newPluginName}
                onChange={(e) => setNewPluginName(e.target.value)}
                data-testid="plugin-name-input"
                aria-label="Plugin name"
              />
            </div>
            <div className="flex-1">
              <label className="text-xs text-muted-foreground mb-1 block">Description</label>
              <Input
                placeholder="Plugin description..."
                value={newPluginDesc}
                onChange={(e) => setNewPluginDesc(e.target.value)}
                data-testid="plugin-desc-input"
                aria-label="Plugin description"
              />
            </div>
            <Button
              onClick={() =>
                installMutation.mutate({
                  name: newPluginName,
                  description: newPluginDesc,
                })
              }
              disabled={!newPluginName.trim() || installMutation.isPending}
              data-testid="plugin-install-btn"
            >
              {installMutation.isPending ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Plus className="mr-2 h-4 w-4" />
              )}
              Install
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Plugin List */}
      {isLoading ? (
        <div className="space-y-3">
          {Array.from({ length: 4 }).map((_, i) => (
            <Skeleton key={i} className="h-20 w-full" />
          ))}
        </div>
      ) : (
        <div className="space-y-3" data-testid="plugin-list">
          {filtered.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              <p>No plugins found{searchText ? ` for "${searchText}"` : ""}.</p>
            </div>
          ) : (
            filtered.map((plugin: Plugin) => (
              <Card key={plugin.name} data-testid={`plugin-card-${plugin.name}`}>
                <CardContent className="flex items-center justify-between py-4">
                  <div className="flex items-center gap-3">
                    <Puzzle className="h-5 w-5 text-muted-foreground" />
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{plugin.name}</span>
                        <Badge variant="outline" className="text-xs">
                          v{plugin.version}
                        </Badge>
                        {plugin.enabled ? (
                          <Badge className="text-xs bg-green-100 text-green-700">Enabled</Badge>
                        ) : (
                          <Badge variant="secondary" className="text-xs">Disabled</Badge>
                        )}
                      </div>
                      <p className="text-sm text-muted-foreground mt-0.5">
                        {plugin.description || "No description"}
                      </p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
          <p className="text-sm text-muted-foreground">
            {data?.total ?? 0} plugin{(data?.total ?? 0) !== 1 ? "s" : ""} total
          </p>
        </div>
      )}
    </div>
  );
}

